const $=s=>document.querySelector(s),esc=v=>String(v??'').replace(/[&<>'"]/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;',"'":'&#39;','"':'&quot;'}[c]));
let selected=null;async function get(u){const r=await fetch(u,{cache:'no-store'});if(!r.ok)throw Error();return r.json()}
async function render(){try{const f=await get('/api/public/events');$('#status-badge').textContent=f.status;if(!selected||!f.events.some(e=>e.id===selected))selected=f.events[0]?.id;$('#event-tabs').innerHTML=f.events.map(e=>`<button class="tab ${e.id===selected?'active':''}" data-id="${esc(e.id)}">${esc(e.name)}</button>`).join('');$('#event-tabs').querySelectorAll('button').forEach(b=>b.onclick=()=>{selected=b.dataset.id;render()});const e=f.events.find(e=>e.id===selected);if(!e){$('#race-title').textContent='No published results';return}const r=await get('/api/public/events/'+encodeURIComponent(selected)+'/results');$('#race-title').textContent=e.name;$('#result-count').textContent=`${r.length} recorded riders`;$('#round-nav').innerHTML='';$('#stage-results').innerHTML=`<div class="race-grid single"><article class="race-table"><header><div><span>Live standings</span><h3>${esc(e.name)}</h3></div><b>${r.length} riders</b></header><div class="table-scroll"><table><thead><tr><th>Pos</th><th>Rider</th><th>Time</th></tr></thead><tbody>${r.map((x,i)=>`<tr class="${i<3?'podium':''}"><td class="place">${x.position}</td><td><span class="rider"><span class="bib">${esc(x.bib)}</span><span class="name">${esc(x.name)}</span></span></td><td class="time">${esc(x.time)}</td></tr>`).join('')}</tbody></table></div></article></div>`}catch{$('#race-title').textContent='Waiting for timing feed';$('#result-count').textContent='The live results service is not connected yet.'}}render();setInterval(render,15000);

